<script setup lang="ts">
import {commandErrorStatus} from '@/composables/aippt/commandError'

defineOptions({name:'AipptCreate'})
import { ref, reactive, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import { useRouter,useRoute,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router'
import {addCloseGuard} from '@/plugins/tab'
import { ElMessageBox } from 'element-plus'
import { api } from '@/api/aippt'
import { ensureCatalog } from '@/composables/aippt/useCatalog'
import { themeList } from '@/views/aippt/render/design'
const router=useRouter(),route=useRoute(),kind=ref('topic'),busy=ref(false),error=ref(''),created=ref(''),topic=ref(''),text=ref(''),files=ref<File[]>([]),failed=ref<string[]>([]),ready=ref(false)
const form=reactive({title:'',audience:'',tone:'professional',page_count:10,layout_mode:'flex',content_density:'medium',theme_id:'ivory'});const initialForm=JSON.stringify(form),formDirty=computed(()=>!created.value&&JSON.stringify(form)!==initialForm)
let removeGuard:(()=>void)|undefined;let createKey=crypto.randomUUID(),sourceKey=crypto.randomUUID();const fileKeys=new Map<File,{key:string;revision:number}>();let sourceBody:Record<string,unknown>|null=null
watch(form,()=>{if(!busy.value&&!created.value)createKey=crypto.randomUUID()},{deep:true});watch([kind,topic,text],()=>{if(!busy.value){sourceKey=crypto.randomUUID();sourceBody=null}})
const valid=computed(()=>!!form.title.trim()&&(kind.value==='document'?files.value.length>0:!!(kind.value==='topic'?topic.value:text.value).trim()))
function addFiles(incoming:File[]){if(busy.value)return;for(const file of incoming)if(!files.value.some(current=>current.name===file.name&&current.size===file.size&&current.lastModified===file.lastModified))files.value.push(file)}
function choose(e:Event){const target=e.target as HTMLInputElement;addFiles(Array.from(target.files||[]));target.value=''}
function dropFiles(e:DragEvent){addFiles(Array.from(e.dataTransfer?.files||[]))}
async function submit(){if(!valid.value)return;busy.value=true;error.value='';failed.value=[]
try{const project=created.value?await api.project(created.value):await api.create(form,createKey);created.value=project.id
 if(kind.value==='document'){for(const file of files.value){try{if(file.size>10*1024*1024)throw new Error('超过10 MiB');if(!/\.(txt|md|docx|pdf)$/i.test(file.name))throw new Error('仅支持TXT、Markdown、DOCX、PDF');const current=await api.project(project.id);let command=fileKeys.get(file);if(!command){command={key:crypto.randomUUID(),revision:current.input_revision};fileKeys.set(file,command)}await api.uploadSource(project.id,file,command.revision,command.key);fileKeys.delete(file);files.value=files.value.filter(f=>f!==file)}catch(e:any){if(commandErrorStatus(e)===409)fileKeys.delete(file);failed.value.push(`${file.name}：${e.message}`)}}}
 else {sourceBody ||= {kind:kind.value,text:kind.value==='topic'?topic.value:text.value,input_revision:(await api.project(project.id)).input_revision};await api.addSource(project.id,sourceBody,sourceKey)}
 if(failed.value.length){error.value='项目与成功材料已保留，可进入项目补充材料。'}else{files.value=[];topic.value='';text.value='';await router.push({path:'/aippt/detail',query:{projectId:project.id}})}
}catch(e:any){if(commandErrorStatus(e)===409){sourceBody=null;sourceKey=crypto.randomUUID()}error.value=e.message||'创建失败，输入已保留'}finally{busy.value=false}}
async function leave(){if(!busy.value&&(!topic.value&&!text.value&&!files.value.length&&!formDirty.value))return true;try{await ElMessageBox.confirm('尚有未提交材料，离开后本页输入将丢失。','保留输入',{confirmButtonText:'离开',cancelButtonText:'继续填写'});return true}catch{return false}}
const unload=(e:BeforeUnloadEvent)=>{if(busy.value||topic.value||text.value||files.value.length||formDirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onMounted(async()=>{removeGuard=addCloseGuard(route.path,leave);window.addEventListener('beforeunload',unload);try{await ensureCatalog();ready.value=true}catch(e:any){error.value=e.message}});onBeforeUnmount(()=>{removeGuard?.();window.removeEventListener('beforeunload',unload)})
</script>
<template><div class="app-container create"><h2>新建演示文稿</h2><p>创建项目后逐份保留材料，失败文件可补传。确认提纲后才开始生成。</p><el-alert v-if="error" type="error" :title="error" show-icon/><el-form label-width="100px" :disabled="busy" @submit.prevent="submit"><el-form-item label="名称" required><el-input v-model="form.title" :disabled="!!created" maxlength="200" show-word-limit/></el-form-item><div class="two"><el-form-item label="受众"><el-input v-model="form.audience" :disabled="!!created" maxlength="100"/></el-form-item><el-form-item label="目标页数"><el-input-number v-model="form.page_count" :disabled="!!created" :min="5" :max="20"/></el-form-item><el-form-item label="语气"><el-select v-model="form.tone" :disabled="!!created"><el-option label="专业" value="professional"/><el-option label="轻松" value="plain"/><el-option label="鼓舞" value="punchy"/></el-select></el-form-item><el-form-item label="排版"><el-select v-model="form.layout_mode" :disabled="!!created"><el-option label="灵活排版" value="flex"/><el-option label="固定版式" value="fixed"/></el-select></el-form-item><el-form-item label="文字量"><el-select v-model="form.content_density" :disabled="!!created"><el-option label="精简" value="concise"/><el-option label="适中" value="medium"/><el-option label="详尽" value="detailed"/></el-select></el-form-item><el-form-item label="主题"><el-select v-model="form.theme_id" :disabled="!ready||!!created"><el-option v-for="t in themeList" :key="t.id" :label="t.name" :value="t.id"/></el-select></el-form-item></div>
<el-tabs v-model="kind"><el-tab-pane label="一句主题" name="topic"><el-input v-model="topic" type="textarea" :rows="5" maxlength="500" show-word-limit placeholder="例如：向产品团队介绍下一季度增长计划"/></el-tab-pane><el-tab-pane label="粘贴文字" name="text"><el-input v-model="text" type="textarea" :rows="10" maxlength="200000" show-word-limit placeholder="粘贴正文，保留段落和标题。模型材料整理预算为总12000字、单小节2000字。"/></el-tab-pane><el-tab-pane label="文档上传" name="document"><label class="upload" @dragover.prevent @drop.prevent="dropFiles">选择 TXT / Markdown / DOCX / 文本 PDF，每文件≤10 MiB<input :disabled="busy" type="file" multiple accept=".txt,.md,.docx,.pdf" @change="choose"/></label><el-table :data="files.map((file,index)=>({name:file.name,size:(file.size/1024).toFixed(1)+' KB',index}))"><el-table-column prop="name" label="文件"/><el-table-column prop="size" label="大小"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="files.splice(row.index,1)">移除</el-button></template></el-table-column></el-table><p>扫描件不提供 OCR；无文字时需补充文本。解析警告将在项目中显示。</p></el-tab-pane></el-tabs><el-button type="primary" :disabled="!valid||!ready" :loading="busy" @click="submit">{{created?'补充材料':'创建并整理材料'}}</el-button><el-button v-if="created" @click="router.push({path:'/aippt/detail',query:{projectId:created}})">进入已创建项目</el-button></el-form><ul><li v-for="message in failed" :key="message">{{message}}</li></ul></div></template>
<style scoped>.create{max-width:1120px}.two{display:grid;grid-template-columns:1fr 1fr;gap:4px 20px}.el-tabs{margin:20px 0}.upload{display:flex;flex-direction:column;gap:12px;border:1px dashed #a8abb2;padding:24px;border-radius:8px}@media(max-width:760px){.two{grid-template-columns:1fr}}</style>
